/* From Uiverse.io by joe-watson-sbf - Tags: summary, card, hover, card template, cardhover , card animation, card hover */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 120px;
  transition: all .5s;
  box-shadow: 15px 15px 30px rgba(25, 25, 25, 0.11),
             -15px -15px 30px rgba(60, 60, 60, 0.082);
  text-align: center;
  overflow: hidden;
}

.__UIV_SCOPE__ .card:hover {
  height: 260px;
  background: linear-gradient(360deg, #edededc5 60%, hsla(0, 0%, 13%, 1) 70%);
}

.__UIV_SCOPE__ .card .header {
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #212121;
  margin-bottom: 16px;
}

.__UIV_SCOPE__ .card .header .img-box {
  width: 50px;
}

.__UIV_SCOPE__ .card .header .title {
  font-size: 1em;
  letter-spacing: .1em;
  font-weight: 900;
  text-transform: uppercase;
  padding: 4px 0 14px 0;
  transition: all .5s;
  color: #edededc5;
}

.__UIV_SCOPE__ .card:hover .header {
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 96%);
}

.__UIV_SCOPE__ .card:hover .card .header .title {
  padding: 0;
}

.__UIV_SCOPE__ .card .content {
  display: block;
  text-align: left;
  color: #212121;
  margin: 0 18px;
}

.__UIV_SCOPE__ .card .content p {
  transition: all .5s;
  font-size: .8em;
  margin-bottom: 8px;
}

.__UIV_SCOPE__ .card .content a {
  color: #1d8122;
  cursor: pointer;
  transition: all .5s;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
}

.__UIV_SCOPE__ .card .content .btn-link:hover {
  border-bottom: 1px solid #1d8122;
}
